contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint _unlockTime, uint _deposit, uint _am) public payable {
        require(address(this).balance >= _deposit);

        // Fund the test contract's account inside c.
        c.Put{value: _deposit}(_unlockTime);

        // Snapshot pre-state of the caller's account and c's Ether balance.
        (uint preUnlockTime, uint preBalance) = c.Acc(_unlockTime, _deposit, _am);
        uint preContractBalance = address(c).balance;

        // Try to collect, with the caller as the recipient (msg.sender here).
        bool reverted;
        try c.Collect(_am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read post-state.
        (uint postUnlockTime, uint postBalance) = c.Acc(_unlockTime, _deposit, _am);
        uint postContractBalance = address(c).balance;

        // Required conditions for the no-revert path.  Note that Collect sets
        // unlockTime to max(_unlockTime, block.timestamp), so the canonical
        // "unlockTime" for the deciding condition is preUnlockTime.
        bool conditionsHeld = (preBalance >= c.MinSum()) && (preBalance >= _am) && (block.timestamp > preUnlockTime);

        if (reverted) {
            // Reverting path: no state change is visible, and no Ether leaves c.
            assert(postBalance == preBalance && postUnlockTime == preUnlockTime && postContractBalance == preContractBalance);
        } else {
            // Success path: must have met all conditions, balance decreased by exactly _am,
            // and c sent exactly _am Ether to the caller.
            assert(conditionsHeld);
            assert(postBalance == preBalance - _am);
            assert(postUnlockTime == preUnlockTime);
            assert(postContractBalance == preContractBalance - _am);
        }
    }
}

